  "buttonFields": [
    {
      "name": "position",
      "label": "Position",
      "kind": "position",
      "required": true,
      "help": "Which slot of the 3 by 3 command panel the button goes in: 1 to 3 is the top row, 7 to 9 the bottom row. The game walks the slots and the buttons together, in order, so a set's buttons must be in ascending position order. A button whose condition hides it takes no slot. A shown button goes in its slot, or in the next one if an earlier shown button already took it, so buttons sharing a position need conditions that never show both. A button past 9 stops the walk, and none after it shows."
    },
    {
      "name": "icon",
      "label": "Icon",
      "kind": "icon",
      "required": true,
      "help": "The frame of unit\\cmdbtns\\cmdicons.grp to show. A frame the file doesn't have shows frame 0 instead."
    },
    {
      "name": "condition",
      "label": "Condition",
      "kind": "condition",
      "required": true,
      "help": "The function that decides whether the button is shown (a positive result), greyed out (negative) or hidden (0)."
    },
    {
      "name": "condition_variable",
      "label": "Condition variable",
      "kind": "conditionVariable",
      "required": false,
      "help": "The value passed to the condition. The game reads it as a byte, so it must be 0 to 255."
    },
    {
      "name": "action",
      "label": "Action",
      "kind": "action",
      "required": true,
      "help": "The function that runs when the button is clicked or its hotkey pressed."
    },
    {
      "name": "action_variable",
      "label": "Action variable",
      "kind": "actionVariable",
      "required": false,
      "help": "The value passed to the action, such as the unit to build or the button card whose buttons to show."
    },
    {
      "name": "enabled_string",
      "label": "Enabled string",
      "kind": "string",
      "required": true,
      "help": "The rez\\stat_txt.tbl string shown as the button's tooltip, counting from 1. Its first character is the hotkey, and its second picks what the tooltip adds to the text, such as the cost."
    },
    {
      "name": "disabled_string",
      "label": "Disabled string",
      "kind": "string",
      "required": true,
      "help": "The rez\\stat_txt.tbl string the tooltip shows instead while the button is greyed out, such as the requirement it lacks. With 0, a greyed-out button shows no tooltip."
    }
  ],
